{
  "name": "mismcp-qwen-edition",
  "version": "0.5.2",
  "description": "opencode multi-agent bus (qwen edition): agents ask each other questions over a shared SQLite queue; single leading system message for Qwen compatibility",
  "type": "module",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/mdementev/mismcp-qwen-edition.git"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "multi-agent",
    "bus"
  ],
  "files": [
    "plugin/mismcp.ts",
    "src/mqwen-agent-id.ts",
    "src/mqwen-config.ts",
    "src/mqwen-store.ts"
  ],
  "main": "plugin/mismcp.ts",
  "exports": {
    ".": "./plugin/mismcp.ts",
    "./server": "./plugin/mismcp.ts"
  },
  "scripts": {
    "typecheck": "tsc --noEmit",
    "build": "tsc --noEmit",
    "test": "node --test \"src/*.test.ts\""
  },
  "engines": {
    "opencode": ">=1.18.0"
  },
  "dependencies": {
    "@opencode-ai/plugin": "^1.18.25"
  },
  "devDependencies": {
    "@opencode-ai/sdk": "^1.18.25",
    "@types/node": "^22.5.0",
    "typescript": "^5.0.0"
  }
}
